def transform(g, bar_over_2=True):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    def is_vline(c): return all(g[r][c]==2 for r in range(H))
    def is_hline(r): return all(g[r][c]==2 for c in range(W))
    vlines=[c for c in range(W) if is_vline(c)]
    hlines=[r for r in range(H) if is_hline(r)]
    markers=[(r,c) for r in range(H) for c in range(W)
             if 0<r<H-1 and 0<c<W-1 and g[r][c]==2 and g[r-1][c]==3 and g[r+1][c]==3 and g[r][c-1]==3 and g[r][c+1]==3]
    protected={(r,c) for (r,c) in markers}
    def paint(r,c):
        if 0<=r<H and 0<=c<W and (r,c) not in protected and g[r][c]!=3: g[r][c]=1
    for (mr,mc) in markers:
        vert = mc in vlines
        targets = [c for c in vlines if c!=mc] if vert else [r for r in hlines if r!=mr]
        for t in targets:
            cr,cc = (mr,t) if vert else (t,mc)
            protected.add((cr,cc))
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    if dr or dc: paint(cr+dr,cc+dc)
            if vert:
                for c2 in range(W): paint(cr,c2)
            else:
                for r2 in range(H): paint(r2,cc)
    return g

